from pathlib import Path
from itertools import permutations
from agreement_middle_patch import apply_middle_mode, apply_recognition_mode
from agreement_weight_patch import apply_pair_weighting


def apply_multiple_answer_hint(source):
    old = '''        if len(adjective_forms) > 1:\n            if st.session_state[widget_key(page_id, "indicate_multiple_answers")]:\n                supplementary.append('<span style="color:#7c3aed;">Több helyes válaszlehetőség van.</span>')\n            else:\n                supplementary.append("Több helyes válaszlehetőség is lehet.")\n'''
    new = '''        if st.session_state[widget_key(page_id, "indicate_multiple_answers")]:\n            if len(adjective_forms) > 1:\n                supplementary.append('<span style="color:#7c3aed;">Több helyes válaszlehetőség is van.</span>')\n        else:\n            supplementary.append("Több helyes válaszlehetőség is lehet.")\n'''
    if old not in source:
        raise RuntimeError("Could not locate agreement multiple-answer hint block")
    return source.replace(old, new, 1)


def apply_weak_istem_is_ambiguity(source):
    old_answers = '''        adjective_forms.sort(key=lambda value: value.casefold())\n        answer_options = [" ".join(items) for items in permutations(adjective_forms)] if adjective_forms else []\n        st.session_state.correct_answer = answer_options\n'''
    new_answers = '''        adjective_forms.sort(key=lambda value: value.casefold())\n        canonical_adjective_forms = list(adjective_forms)\n        accepted_token_sets = {frozenset(form.casefold() for form in adjective_forms)} if adjective_forms else set()\n\n        if ("pl", "acc") in matching_analyses:\n            raw_pl_acc = _am_adjective_form(adjective, "acc", gender, "pl")\n            pl_acc_forms = []\n            pl_acc_seen = set()\n            for item in _am_forms_list(raw_pl_acc):\n                rendered = _am_surface(item, print_macrons)\n                key = rendered.casefold()\n                if key not in pl_acc_seen:\n                    pl_acc_seen.add(key)\n                    pl_acc_forms.append(rendered)\n            if pl_acc_forms:\n                accepted_token_sets.update(\n                    frozenset([form.casefold()]) for form in pl_acc_forms\n                )\n                es_forms = [form for form in pl_acc_forms if str(form).endswith("ēs")]\n                canonical_adjective_forms = es_forms or [pl_acc_forms[-1]]\n\n        weak_istem_is_ambiguity = (\n            noun_vocab[noun].get("decl") == "3_istem"\n            and ("sg", "gen") in matching_analyses\n            and ("pl", "acc") in matching_analyses\n        )\n        if weak_istem_is_ambiguity:\n            def _am_forms_for_analysis(number, case):\n                forms = []\n                seen = set()\n                raw = _am_adjective_form(adjective, case, gender, number)\n                for item in _am_forms_list(raw):\n                    rendered = _am_surface(item, print_macrons)\n                    key = rendered.casefold()\n                    if key not in seen:\n                        seen.add(key)\n                        forms.append(rendered)\n                return forms\n\n            sg_gen_forms = _am_forms_for_analysis("sg", "gen")\n            pl_acc_forms = _am_forms_for_analysis("pl", "acc")\n            canonical_adjective_forms = sg_gen_forms or list(adjective_forms)\n\n            special_forms = []\n            special_seen = set()\n            for form in sg_gen_forms + pl_acc_forms:\n                key = form.casefold()\n                if key not in special_seen:\n                    special_seen.add(key)\n                    special_forms.append(form)\n\n            accepted_token_sets = {frozenset([form.casefold()]) for form in special_forms}\n            for primary in sg_gen_forms:\n                for optional in pl_acc_forms:\n                    accepted_token_sets.add(frozenset([primary.casefold(), optional.casefold()]))\n            if special_forms:\n                accepted_token_sets.add(frozenset(form.casefold() for form in special_forms))\n\n            surface_by_key = {form.casefold(): form for form in special_forms}\n            answer_options = []\n            for accepted_set in accepted_token_sets:\n                values = [surface_by_key[key] for key in accepted_set]\n                answer_options.extend(" ".join(items) for items in permutations(values))\n        else:\n            answer_options = [" ".join(items) for items in permutations(adjective_forms)] if adjective_forms else []\n\n        st.session_state.correct_answer = answer_options\n'''
    if old_answers not in source:
        raise RuntimeError("Could not locate agreement answer-option block")
    source = source.replace(old_answers, new_answers, 1)

    old_check = '''                required = {form.casefold() for form in adjective_forms}\n                supplied = {\n                    _am_surface(token, print_macrons).casefold()\n                    for token in answer_tokens\n                }\n                partial = bool(supplied & required) and supplied != required\n'''
    new_check = '''                answer_macrons = bool(\n                    print_macrons\n                    and st.session_state.get(widget_key(page_id, "enforce_answer_macrons"), False)\n                )\n                required = {\n                    _am_surface(form, answer_macrons).casefold()\n                    for form in canonical_adjective_forms\n                }\n                supplied = {\n                    _am_surface(token, answer_macrons).casefold()\n                    for token in answer_tokens\n                }\n                normalized_accepted_token_sets = {\n                    frozenset(_am_surface(form, answer_macrons).casefold() for form in items)\n                    for items in accepted_token_sets\n                }\n                accepted = (\n                    frozenset(supplied) in normalized_accepted_token_sets\n                    and not duplicate_answer_not_allowed\n                )\n                all_accepted_tokens = (\n                    set().union(*(set(items) for items in normalized_accepted_token_sets))\n                    if normalized_accepted_token_sets else set()\n                )\n                partial = (\n                    bool(supplied & all_accepted_tokens)\n                    and not accepted\n                    and not duplicate_answer_not_allowed\n                )\n'''
    if old_check not in source:
        raise RuntimeError("Could not locate agreement answer-check block")
    source = source.replace(old_check, new_check, 1)

    old_success = '''                    if supplied == required:\n'''
    new_success = '''                    if accepted:\n'''
    if old_success not in source:
        raise RuntimeError("Could not locate agreement success condition")
    source = source.replace(old_success, new_success, 1)

    source = source.replace(
        '''                        correct_text = " ".join(adjective_forms)\n''',
        '''                        correct_text = " ".join(canonical_adjective_forms)\n''',
        2,
    )
    return source


def apply_colored_partial_feedback(source):
    old = '''                partial = (\n                    bool(supplied & all_accepted_tokens)\n                    and not accepted\n                    and not duplicate_answer_not_allowed\n                )\n                if partial:\n                    st.session_state.answer_credit_override = (\n                        0.5 if st.session_state[widget_key(page_id, "award_partial_credit")] else 0\n                    )\n\n                old_macron_setting = st.session_state.enforce_macrons.get("agreement_enforce_macrons", False)\n                st.session_state.enforce_macrons["agreement_enforce_macrons"] = bool(print_macrons)\n                submit_and_check_answer()\n                st.session_state.enforce_macrons["agreement_enforce_macrons"] = old_macron_setting\n\n                if not raw_answer:\n                    st.session_state.answer_display_message = (\n                        "A válaszmező üres. Írd be a megfelelő melléknévi alakot vagy alakokat."\n                    )\n                elif st.session_state.answer_checked:\n                    if accepted:\n                        st.session_state.answer_display_message = feedback_box(\n                            "<strong>Helyes válasz!</strong>", "correct"\n                        )\n                    elif partial:\n                        correct_text = " ".join(canonical_adjective_forms)\n                        st.session_state.answer_display_message = feedback_box(\n                            f"<strong>Részben helyes. A teljes válasz:</strong> {heavy(correct_text, italic=True)}.",\n                            "incorrect",\n                        )\n                    else:\n                        correct_text = " ".join(canonical_adjective_forms)\n                        st.session_state.answer_display_message = feedback_box(\n                            f"<strong>Helytelen válasz. A helyes válasz:</strong> {heavy(correct_text, italic=True)}.",\n                            "incorrect",\n                        )\n'''
    new = '''                partial = (\n                    bool(supplied & all_accepted_tokens)\n                    and not accepted\n                    and not duplicate_answer_not_allowed\n                )\n                partial_credit_enabled = st.session_state[widget_key(page_id, "award_partial_credit")]\n                if partial:\n                    st.session_state.answer_credit_override = 0.5 if partial_credit_enabled else 0\n\n                old_macron_setting = st.session_state.enforce_macrons.get("agreement_enforce_macrons", False)\n                st.session_state.enforce_macrons["agreement_enforce_macrons"] = bool(answer_macrons)\n                submit_and_check_answer()\n                st.session_state.enforce_macrons["agreement_enforce_macrons"] = old_macron_setting\n\n                if not raw_answer:\n                    st.session_state.answer_display_message = (\n                        "A válaszmező üres. Írd be a megfelelő melléknévi alakot vagy alakokat."\n                    )\n                elif st.session_state.answer_checked:\n                    if accepted:\n                        st.session_state.answer_display_message = feedback_box(\n                            "<strong>Helyes válasz!</strong>", "correct"\n                        )\n                    else:\n                        correct_supplied = supplied & all_accepted_tokens\n                        incorrect_supplied = supplied - all_accepted_tokens\n                        missing_required = required - supplied\n\n                        def _form_chip(form, background, border):\n                            return (\n                                f'<span style="display:inline-block;background:{background};border:1px solid {border};'\n                                f'border-radius:0.35rem;padding:0.08rem 0.35rem;margin:0 0.12rem 0.12rem 0;">'\n                                f'{html.escape(str(form))}</span>'\n                            )\n\n                        form_parts = []\n                        for form in sorted(correct_supplied):\n                            form_parts.append(_form_chip(form, "#e3f3e7", "#7aa682"))\n                        for form in sorted(incorrect_supplied):\n                            form_parts.append(_form_chip(form, "#f7dddd", "#c48282"))\n                        for form in sorted(missing_required):\n                            form_parts.append(_form_chip(form, "#e4efff", "#7f9fc9"))\n                        forms_html = " ".join(form_parts)\n\n                        if partial and partial_credit_enabled:\n                            heading = "<strong>Részben helyes válasz.</strong>"\n                            state = "partial"\n                            st.session_state.answer_display_message = feedback_box(\n                                f"{heading} {forms_html}",\n                                state,\n                            )\n                        else:\n                            correct_text = " ".join(canonical_adjective_forms)\n                            st.session_state.answer_display_message = feedback_box(\n                                f"<strong>Helytelen válasz. A helyes válasz:</strong> {heavy(correct_text, italic=True)}.",\n                                "incorrect",\n                            )\n'''
    if old not in source:
        raise RuntimeError("Could not locate agreement feedback block")
    return source.replace(old, new, 1)


stage = Path(__file__).with_name("agreement_stage.py").read_text(encoding="utf-8")
needle = 'exec(compile(source, str(Path(__file__).with_name("agreement_impl.py")), "exec"))'
replacement = (
    'source = apply_middle_mode(source)\n'
    'source = apply_pair_weighting(source)\n'
    'source = apply_recognition_mode(source)\n'
    'source = apply_multiple_answer_hint(source)\n'
    'source = apply_weak_istem_is_ambiguity(source)\n'
    'source = apply_colored_partial_feedback(source)\n'
    + needle
)
if needle not in stage:
    raise RuntimeError("Could not locate agreement stage execution point")
stage = stage.replace(needle, replacement, 1)
exec(compile(stage, str(Path(__file__).with_name("agreement_stage.py")), "exec"))
